<script setup lang="ts">import{onMounted,ref}from"vue";import{ElMessage,ElMessageBox}from"element-plus";import{decideApproval,decideRevocation,listApprovals,listRevocations,type Approval}from"@/api/business";const rows=ref<Approval[]>([]),revocations=ref<any[]>([]),tab=ref("issuance");async function load(){[rows.value,revocations.value]=await Promise.all([listApprovals(),listRevocations()])}async function act(row:Approval,decision:string){const{value}=await ElMessageBox.prompt(decision==='approved'?"填写审批意见（可选）":"填写退回原因","审批决定",{inputType:"textarea",inputValue:""});await decideApproval(row.id,decision,value);ElMessage.success(decision==='approved'?"已通过":"已退回整批名单");await load()}async function revoke(row:any,decision:string){const department=rows.value.find(x=>x.batch_id===row.certificate)?.department||0;const{value}=await ElMessageBox.prompt("请输入本部门 ID（可在竞赛部门配置查看）","作废审批",{inputValue:String(department||"")});await decideRevocation(row.id,Number(value),decision);ElMessage.success(decision==='approved'?"本部门已同意作废":"作废申请已驳回");await load()}onMounted(load);</script>
<template><div class="page"><header><div><h2>会签待办</h2><p>处理签发与作废的部门会签</p></div><el-button @click="load">刷新</el-button></header><el-tabs v-model="tab"><el-tab-pane label="签发审批" name="issuance"><el-table :data="rows" border><el-table-column prop="competition_name" label="竞赛"/><el-table-column prop="batch_name" label="批次"/><el-table-column prop="version_number" label="版本" width="80"/><el-table-column prop="department_name" label="审批部门"/><el-table-column label="决定" width="180"><template #default="s"><el-button link type="success" @click="act(s.row,'approved')">通过</el-button><el-button link type="danger" @click="act(s.row,'returned')">整批退回</el-button></template></el-table-column></el-table></el-tab-pane><el-tab-pane label="作废审批" name="revocation"><el-table :data="revocations" border><el-table-column prop="certificate_number" label="证书编号"/><el-table-column prop="reason" label="原因"/><el-table-column label="进度" width="100"><template #default="s">{{s.row.approved_departments}} / {{s.row.total_departments}}</template></el-table-column><el-table-column prop="status" label="状态" width="100"/><el-table-column label="决定" width="160"><template #default="s"><el-button link type="success" @click="revoke(s.row,'approved')">同意</el-button><el-button link type="danger" @click="revoke(s.row,'rejected')">驳回</el-button></template></el-table-column></el-table></el-tab-pane></el-tabs></div></template><style scoped>.page{padding:20px}header{display:flex;justify-content:space-between;margin-bottom:18px}h2{margin:0;font-size:20px;letter-spacing:0}p{color:#73767a}</style>
